select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:113' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147006 and t.language='nl')='{"text":"Voordat Kareltje de bekende piraat Kromme Kareltje werd, trok hij als kind met zijn ouders in een woonwagen rond. Zijn beste vriendin Hinkelien is steeds dichtbij. Wanneer hun gezelschap aankomt in een dorp waar iedereen gepest lijkt te worden, besluiten de twee er iets aan te doen. Het verhaal laat een eerdere periode zien uit het leven van een personage uit Mus en kapitein Kwaadbaard. Hun avontuur draait om het herkennen van onrecht en het zoeken naar een manier om samen voor anderen op te komen.","work_id":987147006,"evidence":[{"note":"Retain Work2312 De avonturen van Kareltje / Kevin Hassing; exact Dutch De avonturen van Kareltje ISBN 9789021058078 Hardcover. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-035.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p450017214"],"reference":"work:2312","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-035.json","sources":["https://openlibrary.org/works/OL44714690W","https://data.bibliotheken.nl/id/nbt/p450017214"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789021058078","st