eholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789021058078","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15159578,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:37.001Z","editionKey":"/books/OL61062794M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987247007,"bound_title":"De avonturen van Kareltje","reviewed_at":"2026-11-03T09:35:36.993+00:00","bound_isbn13":"9789021058078","evidence_url":"https://data.bibliotheken.nl/id/nbt/p450017214","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987347003}'::jsonb as exact union all select 'catalog_work_descriptions:115' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147007 and t.language='nl')='{"text":"De zestienjarige Claire brengt als flitsbezorger op een koude avond haar laatste bestelling weg. Twee gewapende jongens maken haar vervolgens tot doelwit van een wreed spel. Zonder telefoon, geld, jas of schoenen moet zij vierentwintig uur uit hun handen blijven. Alleen wanneer zij hun regels volgt en niet wordt gevonden, beloven ze haar vrij te laten. Claire ontdekt echter dat de achtervolgers zelf niet eerlijk spelen. Om te overleven moet zij proberen de logica van het spel te doorbreken in plaats van er alleen aan mee te doen.","work_id":987147007,"evidence":[{"note":"Retain Work2317 24 Uur / Marcel van Driel; exact Dutch 24 uur ISBN 9789020609738 Hardcover. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-035.json. No new Work, changed first-publication year, merged author, additional Dutch avail